    const result = await env.DB.prepare(`UPDATE app_themes SET document = ?, etag = ?,
      updated_at = ?, updated_by = ? WHERE id = ? AND etag = ?`)
      .bind(document, etag, updatedAt, ctx.userId, id, expected).run();
    if (!result.meta.changes) return errorResponse(412, 'Theme changed on the server. Reload before publishing.');
  } else if (creating) {
    const result = await env.DB.prepare(`INSERT INTO app_themes (id, document, etag, updated_at, updated_by)
      VALUES (?, ?, ?, ?, ?) ON CONFLICT(id) DO NOTHING`)
      .bind(id, document, etag, updatedAt, ctx.userId).run();
    if (!result.meta.changes) return errorResponse(412, 'Theme already exists. Reload before publishing.');
  } else {
    await env.DB.prepare(`INSERT INTO app_themes (id, document, etag, updated_at, updated_by)
    VALUES (?, ?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET
    document = excluded.document, etag = excluded.etag,
    updated_at = excluded.updated_at, updated_by = excluded.updated_by`)
    .bind(id, document, etag, updatedAt, ctx.userId).run();
  }
  return jsonResponse({ id, etag, updatedAt, url: `/v1/app-themes/${id}` });
}
