/// The SHIPPED tip catalogue, decoded once — the baseline "Reset tips" restores to.
/// The LIVE catalogue is `Theme.current.tips` (see `WACTipCatalogue.catalogue`), which
/// starts equal to this and diverges as tips are added, removed or reordered.
static let bundledTips: [String: [String: RipulKnob]] = bundled.tips

/// Apply a new live theme: update `current`, persist the whole blob (engine slice +
/// extras), then have the engine adopt the slice — it posts `.ripulThemeDidChange`
/// (WAC's `.themeDidChange` alias) and repaints token-tagged UIKit views. Also posts
/// `accentDidChange` — accent lives in the theme now, so long-lived accent-tinted UI
/// (tab bar, etc.) that observes it re-applies whenever the theme changes.
static func apply(_ theme: Theme) {
    jobKinds.receive(theme.jobKindCatalogue)
    current = theme
    if let json = encode(theme) { UserDefaults.standard.set(json, forKey: overrideKey) }
    RipulThemeEngine.adopt(theme.engineDocument)
    NotificationCenter.default.post(name: ThemeManager.accentDidChange, object: nil)
}

/// Drop the local preview (and a "Clear server theme" choice), restore the last accepted server
/// theme — or the bundle when there is none — then check the server for a newer version.
@MainActor
static func resetToAuthoritativeTheme() {
    UserDefaults.standard.removeObject(forKey: shippedThemeKey)
    jobKindPublicationOverride = nil
    jobKinds.clearLocalOverride()
    if let remote = RipulThemeEngine.remoteTheme {
        try? remote.restoreAuthoritativeTheme()
        remote.refreshInBackground()   // restore alone never fetched a newer publication
    } else {
        applyBundledWithoutRemote()
    }
    jobKinds.reload()
}

