//
//  HomeCardEditor.swift
//  WAC
//
//  WYSIWYG editing of Home's card layout, ON Home itself: the real cells with the user's real
//  data, so there is no preview to drift from the screen. Entered from Theme ▸ Home cards (or
//  the `open_screen homeCardEditor` dev tool).
//
//  - Drag the reorder handle to move a card. A move writes rank overrides for EVERY known card
//    kind (absent kinds keep their place relative to the rest), storing only ranks that differ
//    from the default, so dragging back leaves no override behind.
//  - Tap a card for its inspector (a medium sheet, so Home stays visible and updates live
//    behind it): show/hide, where a tap goes, a Test tap, reset.
//  - Hidden cards stay listed while editing, faded, so they can be brought back.
//
//  Edits are ordinary theme overrides, so the Theme hub's Review & publish flow picks them up.
//  While editing, an SDK editing lease holds off server refreshes (which otherwise replace local
//  edits on every foreground); on Done the result is kept as a local preview for this launch.
//
//  Copyright © 2026 Tailwebs. All rights reserved.
//


// MARK: - Layout writes

extension HomeCardLayout {

    static func label(for type: Home.HomeCartType) -> String {
        editable.first { $0.type == type }?.label ?? type.rawValue
    }

    /// Editor name for an element: a built-in card's label, or a custom card's own title.
    static func label(element: String) -> String {
        if let card = HomeCustomCards.card(element) { return card.title.isEmpty ? element : card.title }
        return Home.HomeCartType(rawValue: element).map { label(for: $0) } ?? element
    }

        // Never reuse an id: its layout knobs, and a published copy of it, would be inherited.
        let next = (cards.keys.map(number(in:)).max() ?? 0) + 1
        let id = idPrefix + String(next)
        cards[id] = ["template": .string(Template.iconText.rawValue),
                     "title": .string("New card"),
                     "body": .string("Tap this card while editing to change what it says and where it goes."),
                     "symbol": .string("star")]
        commit(cards)
        HomeCardLayout.move(element: id, below: nil)
        return id
    }

    @MainActor static func update(_ id: String, _ edit: (inout [String: RipulKnob]) -> Void) {
        var cards = catalogue
        guard var knobs = cards[id] else { return }
        edit(&knobs)
        guard knobs != cards[id] else { return }
        cards[id] = knobs
        commit(cards)
    }

    /// Delete the card and its layout knobs together — an orphaned layout entry would otherwise
    /// ride along in every publish.
    @MainActor static func remove(_ id: String) {
        var cards = catalogue
        cards.removeValue(forKey: id)
        var tokens = Theme.current.homeCardTokens
        tokens.removeValue(forKey: id)
        commit(cards, layout: tokens)
    }

