    /// This phone's unpublished editor edits: the saved local theme against the version it was
    /// taken from (the last accepted server document).
    static func localDiff() throws -> [String: Any] {
        guard let local = ThemeProvider.localOverrideDocument else {
            return ["hasLocalEdits": false, "differences": [] as [Any], "count": 0]
        }
        guard let remote = RipulThemeEngine.remoteTheme else {
            throw RipulThemePublishError.invalidResponse
        }
        let base = try JSONSerialization.jsonObject(with: remote.authoritativeDocument)
        let edited = try JSONSerialization.jsonObject(with: local)
        let entries = jsonDiff(base, edited, aName: "server", bName: "local",
                               ignoringEmptyOnlyB: true, ignoringOnlyA: true)
        return ["hasLocalEdits": !entries.isEmpty, "baseVersion": remote.authoritativeETag ?? "",
                "differences": entries, "count": entries.count]
    }

