            throw RipulThemePublishError.invalidDocument
        }
        for key in excludedFromLockstep { shipped[key] = server[key] }
        let data = try JSONSerialization.data(withJSONObject: shipped, options: [.sortedKeys, .prettyPrinted])
        _ = try JSONDecoder().decode(Theme.self, from: data)   // WAC schema check BEFORE any server write
        return data
    }


